import{_ as o,o as r,c as d,ag as a}from"./chunks/framework.KxDd3USm.js";const h=JSON.parse('{"title":"07.8 各语言特点与分类 ★","description":"","frontmatter":{},"headers":[],"relativePath":"07-程序设计语言基础/08-语言特点与分类.md","filePath":"07-程序设计语言基础/08-语言特点与分类.md"}'),n={name:"07-程序设计语言基础/08-语言特点与分类.md"};function s(e,t,g,l,i,p){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="_07-8-各语言特点与分类-★" tabindex="-1">07.8 各语言特点与分类 ★ <a class="header-anchor" href="#_07-8-各语言特点与分类-★" aria-label="Permalink to &quot;07.8 各语言特点与分类 ★&quot;">​</a></h1><p><strong>动机</strong>：选择题常给一个应用场景（&quot;人工智能符号处理&quot;&quot;科学计算&quot;）问选什么语言，或给一个语言问它的分类。记忆表之前先抓两个判断轴：程序是<strong>何时、由谁翻译执行</strong>，变量的类型错误是<strong>何时暴露</strong>。这样看到陌生表述时不用只靠背标签。</p><p><strong>按翻译方式分类</strong>：</p><table tabindex="0"><thead><tr><th>类别</th><th>语言</th></tr></thead><tbody><tr><td>编译型</td><td>C、C++、Pascal、Fortran</td></tr><tr><td>解释型（脚本语言多属此类）</td><td>Python、PHP、JavaScript、Ruby</td></tr><tr><td>先编译为中间代码、再由虚拟机执行</td><td><strong>Java</strong>（字节码 + JVM）、<strong>C#</strong>（中间语言 + .NET）</td></tr></tbody></table><p><strong>静态类型 vs 动态类型</strong>：静态类型语言（C、C++、Java）在<strong>编译期</strong>检查类型；动态类型语言（Python、JavaScript）变量类型在<strong>运行期</strong>才确定、随赋值变化。</p><h3 id="_8-1-两条判断轴-别把-翻译方式-和-类型检查-混在一起" tabindex="-1">8.1 两条判断轴：别把“翻译方式”和“类型检查”混在一起 <a class="header-anchor" href="#_8-1-两条判断轴-别把-翻译方式-和-类型检查-混在一起" aria-label="Permalink to &quot;8.1 两条判断轴：别把“翻译方式”和“类型检查”混在一起&quot;">​</a></h3><p><strong>翻译方式</strong>问的是程序怎样变成可执行动作。以 Java 为例，<code>Order.java</code> 先被编译成与机器无关的字节码 <code>Order.class</code>，再由本机的 JVM 解释或即时编译执行；因此“跨平台”的前提不是把同一份机器码搬到别的机器，而是<strong>各平台有能执行同一字节码的 JVM</strong>。C/C++ 则通常直接编译成目标机器的程序；Python 常由解释器在运行时执行源代码或其内部中间表示。详见<a href="/ruankao/07-程序设计语言基础/01-编译解释与语言成分.html">第 01 节「编译、解释与语言基本成分」</a>。</p><p><strong>类型检查</strong>问的是不合规则的值何时被发现。静态类型语言中，像 <code>int count = &quot;三&quot;;</code> 这类赋值通常在编译期就报错；动态类型语言可先执行 <code>count = 3</code>，以后再执行 <code>count = &quot;三&quot;</code>，变量随当前绑定的值表现出不同类型。反例：Java 是“先编译为字节码再由 JVM 执行”，但它仍是<strong>静态类型</strong>语言；“由虚拟机执行”不等于“动态类型”。</p><p><strong>考场判别</strong>：题干说“逐句翻译、运行时需要解释器”就按翻译方式判断；题干说“给变量赋不相容的值何时出错”才按静态/动态类型判断。这是两条互不替代的轴。</p><p><strong>各语言特点表（背&quot;语言 → 一句话&quot;）</strong>：</p><table tabindex="0"><thead><tr><th>语言</th><th>一句话特点</th></tr></thead><tbody><tr><td>Fortran</td><td>科学计算，执行效率高</td></tr><tr><td>Pascal</td><td>为教学而开发，表达能力强</td></tr><tr><td>C</td><td>指针操作能力强、高效，常用于操作系统开发</td></tr><tr><td><strong>Lisp</strong></td><td><strong>函数式</strong>语言，符号处理，<strong>人工智能</strong></td></tr><tr><td><strong>Prolog</strong></td><td><strong>逻辑推理</strong>，用于数据库和专家系统</td></tr><tr><td>C++</td><td>面向对象且高效</td></tr><tr><td>Java</td><td>面向对象，编译为中间代码（字节码），跨平台</td></tr><tr><td>C#</td><td>面向对象，中间代码，.NET 平台</td></tr><tr><td>Python</td><td>解释型、面向对象、通用脚本语言</td></tr><tr><td>PHP</td><td>服务器端脚本语言，嵌入 HTML 的动态网页</td></tr></tbody></table><h3 id="_8-2-lisp-与-prolog-都能做-ai-但解决问题的问法不同" tabindex="-1">8.2 Lisp 与 Prolog：都能做 AI，但解决问题的问法不同 <a class="header-anchor" href="#_8-2-lisp-与-prolog-都能做-ai-但解决问题的问法不同" aria-label="Permalink to &quot;8.2 Lisp 与 Prolog：都能做 AI，但解决问题的问法不同&quot;">​</a></h3><ul><li><strong>Lisp</strong>擅长把符号和列表当作数据来处理。例如要把一棵表达式树 <code>(+ x 1)</code> 改写为 <code>(+ y 1)</code>，重点是“如何用函数递归处理符号结构”，这是函数式/符号处理的画面。</li><li><strong>Prolog</strong>擅长先写事实和规则，再让系统推理查询。例如已知“甲是乙的父亲”“乙是丙的父亲”，写出“父亲关系可推出祖先关系”后，询问“甲是不是丙的祖先”，重点是“根据规则能否推出结论”。</li></ul><p>反例：题干出现“专家系统依据规则和事实推出诊断结论”，应选 <strong>Prolog</strong>，不是因为它“也与 AI 有关”就选 Lisp；题干强调递归处理列表、符号表达式或函数组合，才更接近 <strong>Lisp</strong>。</p><p><strong>应试动作</strong>：重点背两个&quot;最容易和别的搞混&quot;的——<strong>Lisp=函数式/AI</strong>、<strong>Prolog=逻辑推理/专家系统</strong>（两者都沾 AI，别互换）；再背 Java 跨平台靠&quot;字节码 + JVM&quot;这条机制描述。其余扫一眼有印象即可。</p><hr>',16)])])}const _=o(n,[["render",s]]);export{h as __pageData,_ as default};
